import data.glitch_lib

suspicious_patterns := {"TODO", "FIXME", "BUG", "HACK", "LATER", "XXX", "OPTIMIZE", "REFACTOR", "WORKAROUND", "TEMPORARY", "INCOMPLETE", "DIRTY", "KLUDGE", "No authentication", "Default password", "Insecure", "Vulnerable", "Bypass", "Hardcoded credential", "No validation", "Skip check", "Memory leak", "Race condition", "Slow", "Timeout", "Unstable", "NOTE", "Currently", "cannot change", "break", "deprecated", "obsolete"}

Glitch_Analysis[result] {
    walk(input, [path, node])
    node.ir_type == "Comment"
    node.line > 0
    pattern := suspicious_patterns[_]
    contains(node.content, pattern)
    parent_unit_block := _find_parent_unit_block(path)
    result := {
        "type": "sec_susp_comm",
        "element": node,
        "path": parent_unit_block.path,
        "description": "Suspicious comment found that may indicate a bug, incomplete functionality, or security weakness. (CWE-546)"
    }
}

_find_parent_unit_block(path) = unit_block {
    # Walk backwards through the path to find the nearest UnitBlock
    some i
    path[i].ir_type == "UnitBlock"
    unit_block := path[i]
} else = unit_block {
    # If no UnitBlock in path, use the input project's first module's first unit block
    unit_block := input.modules[0].blocks[0]
}
